nativeFiles.package/android/build.gradle:
// Module-level build.gradle for react-native-litert-lm
// Configures Android build with Kotlin HybridObject + C++ JNI glue

plugins {
    id 'com.android.library'
    id 'org.jetbrains.kotlin.android'
}

// Apply Nitrogen autolinking
apply from: '../nitrogen/generated/android/LiteRTLM+autolinking.gradle'

// Read LiteRT-LM SDK version from package.json (single source of truth)
def packageJson = new groovy.json.JsonSlurper().parseText(file('../package.json').text)
def litertLmVersion = packageJson.litertLm.androidMavenVersion

android {
    namespace "dev.litert.litertlm"
    compileSdk 36

    defaultConfig {
        minSdk 26  // LiteRT-LM requires API 26+
        consumerProguardFiles 'consumer-rules.pro'
        // On-device inference tests (src/androidTest) — Robolectric can't run
        // the LiteRT-LM engine. Skipped unless a .litertlm bundle is pushed to
        // the test app's external files dir; see HybridLiteRTLMInstrumentedTest.
        testInstrumentationRunner "androidx.test.runner.AndroidJUnitRunner"

        externalNativeBuild {
            cmake {
                cppFlags "-O2 -fexceptions -frtti -std=c++20"
                arguments "-DANDROID_STL=c++_shared"
            }
        }

        ndk {
            abiFilters 'arm64-v8a'
        }
    }

    buildFeatures {
        prefab true
    }

    externalNativeBuild {
        cmake {
            path "CMakeLists.txt"
            version "3.22.1"
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = '17'
    }

    sourceSets {
        main {
            java.srcDirs += [
                'src/main/java',
                '../nitrogen/generated/android/kotlin'
            ]
        }
    }

    packaging {
        jniLibs {
            keepDebugSymbols.add("**/*.so")
            // The androidTest APK pulls these from several inputs at once (our
            // CMake output, ReactAndroid, fbjni). They are the same ABI-compatible
            // libraries — take the first instead of failing the merge.
            pickFirsts.add("**/libc++_shared.so")
            pickFirsts.add("**/libfbjni.so")
        }
    }

    testOptions {
        unitTests {
            includeAndroidResources = true
        }
    }
}

repositories {
    google()
    mavenCentral()
}

// litertlm-android is compiled with Java 21 (class file 65). Robolectric loads
// those classes into the test JVM, so unit tests must run on a 21+ launcher
// even though the library itself targets 17. Gradle auto-detects installed
// JDKs; add org.gradle.java.installations.paths if yours lives elsewhere.
tasks.withType(Test).configureEach {
    javaLauncher.set(javaToolchains.launcherFor {
        languageVersion.set(JavaLanguageVersion.of(21))
    })
}

dependencies {
    // React Native
    implementation 'com.facebook.react:react-android'

    // Nitro Modules
    implementation project(':react-native-nitro-modules')

    // fbjni for HybridObject JNI bridge
    implementation 'com.facebook.fbjni:fbjni:0.6.0'

    // Kotlin coroutines for async operations
    implementation 'org.jetbrains.kotlinx:kotlinx-coroutines-core:1.7.3'
    implementation 'org.jetbrains.kotlinx:kotlinx-coroutines-android:1.7.3'

    // LiteRT-LM Kotlin API
    implementation "com.google.ai.edge.litertlm:litertlm-android:${litertLmVersion}"

    // Testing Dependencies
    testImplementation 'junit:junit:4.13.2'
    testImplementation 'org.robolectric:robolectric:4.11.1'
    testImplementation 'org.jetbrains.kotlinx:kotlinx-coroutines-test:1.7.3'
    // Local HTTPS server for HybridModelStore download tests
    testImplementation 'com.squareup.okhttp3:mockwebserver:4.12.0'
    testImplementation 'com.squareup.okhttp3:okhttp-tls:4.12.0'

    // On-device instrumented tests (real engine, real model)
    androidTestImplementation 'junit:junit:4.13.2'
    androidTestImplementation 'androidx.test:runner:1.5.2'
    androidTestImplementation 'androidx.test.ext:junit:1.1.5'
    // Nitro's Promise goes through fbjni HybridData, whose NativeLoader an RN
    // app initializes at startup — the test APK does it explicitly.
    androidTestImplementation 'com.facebook.soloader:nativeloader:0.12.1'
}
